+//! Reads complete resolved runs and atomically publishes them to PostgreSQL.
+
+use std::{
+    collections::{BTreeMap, BTreeSet},
+    fs,
+    path::{Path, PathBuf},
+};
+
+use arrow::datatypes::{DataType, Field, Schema};
+use chrono::{DateTime, NaiveDate, Utc};
+use serde::Deserialize;
+use sha2::{Digest, Sha256};
+use sqlx::Row;
+use uuid::Uuid;
+
+use super::{
+    ExposedDataPipeline,
+    declaration_cleaning::{self, CapturedMemberDeclarations, CleanedFundingEntry},
+    declaration_resolution::{self, read_table},
+    postgres::ExposedDatabase,
+};
+use crate::domain::{
+    models::{
+        declaration_cleaning::FunderObservation,
+        declaration_loading::{
+            DeclarationLoad, DeclarationLoadSummary, LoadDeclaration, LoadFundingEntry, LoadFunder,
