+            if attributions.insert(funding_id, row).is_some() {
+                return Err(data_error("duplicate funding attribution"));
+            }
+        }
+        let mut selected_identity_ids = BTreeSet::new();
+        let mut funding_entries = Vec::with_capacity(payments.len());
+        for payment in payments {
+            let declaration = declarations
+                .get(&payment.declaration_id)
+                .ok_or_else(|| data_error("cleaned funding row references a missing declaration"))?;
+            if payment.member_id != declaration.member_id.to_string()
+                || payment.parliament_member_id != declaration.parliament_member_id
+                || payment.category_id != declaration.category_id
+                || payment.category_name != declaration.category_name
+                || payment.fetched_at != declaration.fetched_at
+                || payment.registration_date != declaration.registration_date
+            {
+                return Err(data_error("cleaned funding row disagrees with raw declaration metadata"));
+            }
+            let attribution = attributions
+                .remove(payment.funding_entry_id.as_str())
+                .ok_or_else(|| data_error("funding entry has no resolved attribution"))?;
+            let (selected_observation_id, identity_id, attribution_basis, parent_id, unavailable_reason, issues) =
+                match attribution {
+                    AttributionRow::Selected { selected_funder_id, attribution_basis, selected_parent_declaration_id, issues, .. } => {
+                        let identity_id = identities
+                            .get(&selected_funder_id)
+                            .ok_or_else(|| data_error("attribution references a missing observation"))?
+                            .clone();
+                        let identity_id = identity_id.ok_or_else(|| data_error("selected observation has no resolved identity"))?;
+                        selected_identity_ids.insert(identity_id.clone());
+                        (Some(selected_funder_id), Some(identity_id), Some(attribution_basis), selected_parent_declaration_id, None, issues)
+                    }
+                    AttributionRow::Unavailable { unavailable_reason, issues, .. } => {
+                        (None, None, None, None, Some(unavailable_reason), issues)
+                    }
+                };
+            funding_entries.push(LoadFundingEntry {
+                source_id: payment.funding_entry_id,
+                source_declaration_id: payment.declaration_id,
+                identity_id,
+                selected_observation_id,
+                attribution_basis,
+                selected_parent_declaration_id: parent_id,
+                unavailable_reason,
+                issues,
+                amount: payment.funding.amount().map(str::to_owned),
+                currency: payment.funding.currency().map(str::to_owned),
+                payment_type: payment.funding.payment_type().map(str::to_owned),
+            });
+        }
+        if !attributions.is_empty() {
+            return Err(data_error("resolved output contains an attribution without a funding entry"));
+        }
+        if identities.values().any(Option::is_none) {
+            return Err(data_error("current resolver policy requires every observation to have an identity"));
+        }
+
+        let mut funder_groups = BTreeMap::<String, Vec<&FunderObservation>>::new();
+        for (observation_id, identity_id) in &identities {
+            let identity_id = identity_id.as_ref().expect("checked resolved identity");
+            if selected_identity_ids.contains(identity_id) {
+                funder_groups.entry(identity_id.clone()).or_default().push(&observations[observation_id]);
+            }
+        }
+        let mut load_funders = Vec::with_capacity(funder_groups.len());
+        for (identity_id, mut group) in funder_groups {
+            group.sort_by(|left, right| left.funder_id.cmp(&right.funder_id));
+            let company_number = group.iter().find_map(|row| row.donor_company_number.clone());
+            let kind = group.iter().find_map(|row| row.donor_kind.clone());
+            let name = group.iter().find_map(|row| row.name.raw.clone()).unwrap_or_else(|| {
+                company_number.as_ref().map_or_else(
+                    || "Unnamed resolved funder".to_owned(),
+                    |number| format!("Companies House {number}"),
+                )
+            });
+            load_funders.push(LoadFunder { identity_id, name, kind, company_number });
+        }
