+        let fingerprint = fingerprint_files(
+            raw_paths.iter().cloned().chain([
+                cleaned.join("funders.parquet"),
+                cleaned.join("funding_entries.parquet"),
+                resolved.join("observation_resolution.parquet"),
+                resolved.join("payment_attribution.parquet"),
+                resolved.join("pair_decisions.parquet"),
+                resolved.join("manifest.json"),
+            ]),
+        )?;
+        DeclarationLoad::checked(
+            self.key().into(),
+            fingerprint,
+            declarations.into_values().collect(),
+            load_funders,
+            funding_entries,
+        )
+    }
+}
+
+#[derive(Deserialize)]
+struct ResolutionManifest {
+    schema_version: u32,
+    policy_version: String,
+    input_sha256: BTreeMap<String, String>,
+    observations: usize,
+    payments: usize,
+    pair_decisions: usize,
+}
+
+#[derive(Deserialize)]
+struct IdentityRow {
+    funder_id: String,
+    identity_id: Option<String>,
+}
+impl IdentityRow {
+    fn observation_id(&self) -> String { self.funder_id.clone() }
+}
+
+#[derive(Deserialize)]
+struct PairRow {
+    left_funder_id: String,
+    right_funder_id: String,
+    probability: f64,
+}
+
+#[derive(Deserialize)]
